#!/bin/bash
# Stage 1 swap check only. Each run gets a fresh DSH_HOME; never uses ~/.dsh.
# Prerequisite: build and pack the three bundles into dsh-plugins/dist/.
# Usage: run-prime-memory.sh [port]
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
engine="$(cd "$here/../../.." && pwd)"
port="${1:-8321}"
dsh="$engine/build/dsh-runtime/0.2.0-rc.2/node_modules/.bin/dsh"
out="$engine/results/dsh/prime_memory_swap"
mkdir -p "$engine/build/dsh-home-prime" "$out"
# These files are generated by this runner; discard the previous run's evidence.
rm -f "$out/probe.json" "$out/memory.log" "$out/run.json" "$out"/stats-*.json
export DSH_HOME
DSH_HOME="$(mktemp -d "$engine/build/dsh-home-prime/run.XXXXXX")"
export DSH_TELEMETRY_DISABLED=1
pid=''
cleanup() {
  if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
    kill -TERM "$pid"
    wait "$pid" || true
  fi
}
trap cleanup EXIT
"$dsh" plugin --profile memtest add dsh-prime-memory@0.22.1 \
  "$engine/dsh-plugins/dist/dsh-text-embeddings-0.1.0.tgz" \
  "$engine/dsh-plugins/dist/dsh-text-embeddings-tsuzuki-0.1.0.tgz" \
  "$engine/dsh-plugins/dist/dsh-text-embeddings-openai-0.1.0.tgz" > "$out/plugin-add.txt" 2>&1
cat > "$DSH_HOME/profiles/memtest/cordis.patch.yml" <<YAML
- id: text-embeddings-tsuzuki
  disabled: false
  config:
    engineRoot: '$engine'
    port: $port
- id: dsh-memory
  config:
    dataDir: '$DSH_HOME/memory'
    capture:
      enabled: false
    extract:
      enabled: false
    l2:
      enabled: false
    l3:
      enabled: false
    live:
      capture: false
      distill: false
      memoryMutate: true
    embedding:
      enabled: true
      baseUrl: http://127.0.0.1:$port/v1
      apiKey: ''
      model: embeddinggemma-2
      dimensions: 768
      allowLocalModels: false
    recall:
      strategy: hybrid
- insert:
    - id: prime-test-webserver
      name: '@deepseek-ai/dsh-host-webserver'
      config:
        host: 127.0.0.1
        port: 0
    - id: prime-test-connection
      name: '@deepseek-ai/dsh-client-connection'
YAML
cp "$DSH_HOME/profiles/memtest/cordis.patch.yml" "$out/profile.patch.yml"
cat > "$out/probe.patch.yml" <<YAML
- insert:
    - id: prime-memory-probe
      name: '$here/prime-memory-probe.mjs'
      config:
        origin: http://127.0.0.1:$port
        out: '$out'
YAML
"$dsh" --profile memtest --dump-config > "$out/dump-config.yml" 2>&1
"$dsh" --profile memtest --patch "$out/probe.patch.yml" > "$out/boot.txt" 2>&1 & pid=$!
timed_out=false
for i in $(seq 1 90); do
  kill -0 "$pid" 2>/dev/null || break
  sleep 1
done
if kill -0 "$pid" 2>/dev/null; then
  timed_out=true
  kill -TERM "$pid"
fi
status=0
wait "$pid" || status=$?
pid=''
[ "$timed_out" = false ] || status=124
if [ -f "$DSH_HOME/memory/memory.log" ]; then
  cp "$DSH_HOME/memory/memory.log" "$out/memory.log"
else
  status=10
fi
node --input-type=module - "$out/probe.json" <<'JS' || status=11
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
assert.equal(JSON.parse(readFileSync(process.argv[2], 'utf8')).ok, true)
JS
sleep 1
stopped=true
if curl --max-time 2 -sf "http://127.0.0.1:$port/health" > /dev/null; then stopped=false; status=9; fi
if [ -f "$out/memory.log" ]; then
  if rg -ni 'embeddings HTTP|embedding 维度不匹配|embeddings 返回数量不匹配|远程.*失败|向量.*失败|嵌入.*失败|embed.*failed|fetch failed|ECONN|ETIMEDOUT' "$out/memory.log" > "$out/embedding-errors.txt"; then status=10; fi
fi
cat > "$out/run.json" <<JSON
{"dsh":"0.2.0-rc.2","primeMemory":"0.22.1","dshHome":"$DSH_HOME","telemetryDisabled":true,"apiKeyConfigured":false,"port":$port,"exit":$status,"timedOut":$timed_out,"daemonStopped":$stopped}
JSON
cat "$out/run.json"
if [ -f "$out/probe.json" ]; then cat "$out/probe.json"; else tail -40 "$out/boot.txt"; fi
exit "$status"
